 "<div style=\"text-align:center\"><b style=\"font-size:28px;color:#fcd34d\">1 · Idea</b><br><span style=\"font-size:21px;color:#d9d4f2\">Un congresista presenta un proyecto</span></div>": "<div style=\"text-align:center\"><b style=\"font-size:28px;color:#fcd34d\">1 · Idea</b><br><span style=\"font-size:21px;color:#d9d4f2\">Un congressista presenta un projecte</span></div>",
 "Una carpeta": "Una carpeta",
