 "<div style=\"text-align:center\"><b style=\"font-size:30px;color:#7dd3fc\">Sé responsable</b><br><span style=\"font-size:23px;color:#d9d4f2\">Haz tu parte</span></div>": "<div style=\"text-align:center\"><b style=\"font-size:30px;color:#7dd3fc\">Sigues responsable</b><br><span style=\"font-size:23px;color:#d9d4f2\">Fes la teva part</span></div>",
